/* prog50_binary_heap.c
 *
 * A tiny command‑line binary min‑heap with a fixed capacity of 16.
 *
 * Behaviour (exactly as the original binary):
 *
 *   * If the program is invoked without any arguments it prints:
 *         NOOP
 *
 *   * For each argument (processed left‑to‑right):
 *
 *       -  "I<number>"   – insert the signed decimal integer <number>.
 *                         * If the heap already contains 16 elements:
 *                               prints "FULL"
 *                         * otherwise inserts the value and prints
 *                               INS %ld\n   (the inserted value)
 *
 *       -  "X"           – extract the minimum element.
 *                         * If the heap is empty prints "EMPTY"
 *                         * otherwise removes the smallest element and prints
 *                               MIN %ld\n   (the extracted value)
 *
 *       -  any other argument prints "ERR".
 *
 *   All messages are terminated by a newline (exactly as the original
 *   program does – `puts` for the fixed strings and `printf` for the
 *   formatted ones).
 *
 *   The implementation uses a classic binary min‑heap stored in a static
 *   array `heap[16]`.  The heap invariant is maintained after each
 *   insertion (sift‑up) and extraction (sift‑down).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAPACITY 16

static long heap[CAPACITY];
static int  size = 0;               /* current number of elements */

/* -------------------------------------------------------------
 * Helper: swap two elements in the heap array.
 * ------------------------------------------------------------- */
static void swap(int i, int j)
{
    long tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

/* -------------------------------------------------------------
 * Insert a value into the heap.
 * Returns 0 on success, 1 if the heap is already full.
 * ------------------------------------------------------------- */
static int heap_insert(long value)
{
    if (size >= CAPACITY)
        return 1;                       /* FULL */

    /* place the new element at the end */
    int i = size;
    heap[i] = value;
    ++size;

    /* sift‑up to restore the min‑heap property */
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[parent] <= heap[i])
            break;
        swap(parent, i);
        i = parent;
    }
    return 0;
}

/* -------------------------------------------------------------
 * Extract the minimum element from the heap.
 * Returns 0 on success (value stored in *out), 1 if the heap is empty.
 * ------------------------------------------------------------- */
static int heap_extract_min(long *out)
{
    if (size == 0)
        return 1;                       /* EMPTY */

    *out = heap[0];                     /* the minimum */

    /* move the last element to the root and shrink the heap */
    heap[0] = heap[size - 1];
    --size;

    /* sift‑down to restore the min‑heap property */
    int i = 0;
    while (1) {
        int left  = 2 * i + 1;
        int right = 2 * i + 2;
        int smallest = i;

        if (left < size && heap[left] < heap[smallest])
            smallest = left;
        if (right < size && heap[right] < heap[smallest])
            smallest = right;

        if (smallest == i)
            break;

        swap(i, smallest);
        i = smallest;
    }
    return 0;
}

/* -------------------------------------------------------------
 * Main – processes the command‑line arguments exactly as the
 * original binary does.
 * ------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int idx = 1; idx < argc; ++idx) {
        char *arg = argv[idx];

        if (arg[0] == 'I') {
            /* Parse the number after the leading 'I' */
            char *endptr;
            long val = strtol(arg + 1, &endptr, 10);

            if (endptr == arg + 1 || *endptr != '\0') {
                puts("ERR");
                continue;
            }

            if (heap_insert(val)) {
                puts("FULL");
            } else {
                printf("INS %ld\n", val);
            }
        }
        else if (strcmp(arg, "X") == 0) {
            long min;
            if (heap_extract_min(&min)) {
                puts("EMPTY");
            } else {
                printf("MIN %ld\n", min);
            }
        }
        else {
            puts("ERR");
        }
    }
    return 0;
}
